import { headers } from 'next/headers'

async function getDashboardData(url: string): Promise<unknown> {
  const response = await fetch(url)
  if (!response.ok) throw new Error(`Dashboard request failed: ${response.status}`)
  return response.json()
}

export default async function Dashboard() {
  // Server-side fetch requires absolute URLs for the local API routes.
  const requestHeaders = await headers()
  const host = requestHeaders.get('x-forwarded-host') ?? requestHeaders.get('host')
  if (!host) return <p>Dashboard data is unavailable.</p>

  const protocol = requestHeaders.get('x-forwarded-proto') ?? 'http'
  const origin = `${protocol}://${host}`

  try {
    const [analytics, notifications, settings] = await Promise.all([
      getDashboardData(new URL('/api/analytics', origin).toString()),
      getDashboardData(new URL('/api/notifications', origin).toString()),
      getDashboardData(new URL('/api/settings', origin).toString()),
    ])

    return (
      <div>
        <h2>Dashboard Content</h2>
        <section>
          <h3>Analytics</h3>
          <pre>{JSON.stringify(analytics, null, 2)}</pre>
        </section>
        <section>
          <h3>Notifications</h3>
          <pre>{JSON.stringify(notifications, null, 2)}</pre>
        </section>
        <section>
          <h3>Settings</h3>
          <pre>{JSON.stringify(settings, null, 2)}</pre>
        </section>
      </div>
    )
  } catch {
    return <p>Dashboard data is unavailable.</p>
  }
}

