import { afterEach, expect, it, vi } from 'vitest'
import { renderToStaticMarkup } from 'react-dom/server'
import Dashboard from './Dashboard'

vi.mock('next/headers', () => ({
  headers: async () => new Headers({ host: 'localhost:3000' }),
}))

afterEach(() => vi.unstubAllGlobals())

it('starts all three requests before awaiting them and displays their data', async () => {
  const resolveRequests: Array<(response: Response) => void> = []
  const fetchMock = vi.fn(
    () => new Promise<Response>((resolve) => resolveRequests.push(resolve))
  )
  vi.stubGlobal('fetch', fetchMock)

  const dashboard = Dashboard()
  await vi.waitFor(() => expect(fetchMock).toHaveBeenCalledTimes(3))
  expect(fetchMock.mock.calls.map(([url]) => url)).toEqual([
    'http://localhost:3000/api/analytics',
    'http://localhost:3000/api/notifications',
    'http://localhost:3000/api/settings',
  ])

  for (const [index, data] of [
    { views: 10 },
    [{ message: 'New notification' }],
    { theme: 'dark' },
  ].entries()) {
    resolveRequests[index](new Response(JSON.stringify(data)))
  }

  const html = renderToStaticMarkup(await dashboard)
  expect(html).toContain('Analytics')
  expect(html).toContain('10')
  expect(html).toContain('New notification')
  expect(html).toContain('dark')
})

it('shows an unavailable message when an API request fails', async () => {
  vi.stubGlobal('fetch', vi.fn(async () => new Response('Not found', { status: 404 })))
  const html = renderToStaticMarkup(await Dashboard())
  expect(html).toContain('Dashboard data is unavailable.')
})

