'use client'

import { useEffect, useState } from 'react'

type DashboardData = {
  analytics: unknown
  notifications: unknown
  settings: unknown
}

async function fetchJson(url: string): Promise<unknown> {
  const response = await fetch(url)
  if (!response.ok) throw new Error(`Dashboard request failed: ${response.status}`)
  return response.json()
}

export async function getDashboardData(): Promise<DashboardData> {
  const [analytics, notifications, settings] = await Promise.all([
    fetchJson('/api/analytics'),
    fetchJson('/api/notifications'),
    fetchJson('/api/settings'),
  ])

  return { analytics, notifications, settings }
}

export default function Dashboard() {
  const [data, setData] = useState<DashboardData | null>(null)
  const [error, setError] = useState(false)

  useEffect(() => {
    let active = true

    getDashboardData()
      .then((result) => {
        if (active) setData(result)
      })
      .catch(() => {
        if (active) setError(true)
      })

    return () => {
      active = false
    }
  }, [])

  return (
    <div>
      <h2>Dashboard Content</h2>
      {error ? (
        <p>Dashboard data is unavailable.</p>
      ) : data ? (
        <>
          <section>
            <h3>Analytics</h3>
            <pre>{JSON.stringify(data.analytics, null, 2)}</pre>
          </section>
          <section>
            <h3>Notifications</h3>
            <pre>{JSON.stringify(data.notifications, null, 2)}</pre>
          </section>
          <section>
            <h3>Settings</h3>
            <pre>{JSON.stringify(data.settings, null, 2)}</pre>
          </section>
        </>
      ) : (
        <p>Loading dashboard data...</p>
      )}
    </div>
  )
}

